#include "stdlib/napi/argv_int32.h"
#include "stdlib/assert/napi/status_ok.h"
#include "stdlib/assert/napi/is_type.h"
#include <node_api.h>
#include <stdint.h>
#include <stdbool.h>

/**
* Converts a Node-API value to a signed 32-bit integer.
*
* @param env       environment under which the function is invoked
* @param value     Node-API value
* @param out       destination for storing output value
* @param message   error message
* @param err       pointer for storing a JavaScript error
* @return          status code indicating success or failure (returns `napi_ok` if success)
*
* @example
* #include "stdlib/napi/argv_int32.h"
* #include <node_api.h>
* #include <stdint.h>
*
* static napi_value addon( napi_env env, napi_callback_info info ) {
*     napi_value value;
*
*     // ...
*
*     int32_t out;
*     napi_value err;
*     napi_status status = stdlib_napi_argv_int32( env, value, &out, "Must be a number.", &err );
*     assert( status == napi_ok );
*     if ( err != NULL ) {
*         assert( napi_throw( env, err ) == napi_ok );
*         return NULL;
*     }
*
*     // ...
* }
*/
napi_status stdlib_napi_argv_int32( const napi_env env, const napi_value value, int32_t *out, const char *message, napi_value *err ) {
	bool lossless = true;
	int64_t tmp = 0;

	stdlib_assert_napi_value_is_type( env, value, napi_number, message, err );
	if ( *err == NULL ) {
		STDLIB_ASSERT_NAPI_STATUS_OK_RET_VALUE( env, napi_get_value_int32( env, value, out ), "", napi_ok )
		return napi_ok;
	}
	*err = NULL;
	stdlib_assert_napi_value_is_type( env, value, napi_bigint, message, err );
	if ( *err == NULL ) {
		STDLIB_ASSERT_NAPI_STATUS_OK_RET_VALUE( env, napi_get_value_bigint_int64( env, value, &tmp, &lossless ), "", napi_ok )
		*out = (int32_t)(tmp);
		return napi_ok;
	}
	return napi_ok;
}","lineStart":1,"lineEnd":75,"totalLines":75,"truncated":false}},"title":"repos/pc-lib-3456/napi-argv-int32/src/main.c","time":{"start":1783261722913,"end":1783261722917}},"id":"prt_f32ae78350010jQaJeKUViEEL1","sessionID":"ses_0cd51e53fffe3wadErbCsWJE3P","messageID":"msg_f32ae70df0017bEjmQ8Te7R7HO"}}

