'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Number = require( '@stdlib/number-ctor' );
var BigInt = require( '@stdlib/bigint-ctor' );
var hasBigIntSupport = require( '@stdlib/assert-has-bigint-support' );
var tryRequire = require( '@stdlib/utils-try-require' );


// VARIABLES //

var addon = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( addon instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof addon, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided an argument which is not a number', opts, function test( t ) {
	var values;
	var i;

	values = [
		'5',
		true,
		false,
		null,
		void 0,
		[],
		{}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided '+values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			addon( value );
		};
	}
});

tape( 'the function does not throw an error if provided a number', opts, function test( t ) {
	var values;
	var v;
	var i;

	values = [
		5,
		-5,
		0
	];
	for ( i = 0; i < values.length; i++ ) {
		v = addon( values[ i ] );
		t.strictEqual( v, values[ i ], 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});

opts.skip = opts.skip || !hasBigIntSupport();
tape( 'the function does not throw an error if provided a BigInt', opts, function test( t ) {
	var values;
	var v;
	var i;

	values = [
		BigInt( 5 ),
		BigInt( -5 ),
		BigInt( 0 )
	];
	for ( i = 0; i < values.length; i++ ) {
		v = addon( values[ i ] );
		t.strictEqual( v, Number( values[ i ] ), 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});","lineStart":1,"lineEnd":105,"totalLines":105,"truncated":false}},"title":"repos/pc-lib-3456/napi-argv-int32/test/test.native.js","time":{"start":1783261744620,"end":1783261744623}},"id":"prt_f32aecdc6001ZbU1C0QPB8vy57","sessionID":"ses_0cd51e53fffe3wadErbCsWJE3P","messageID":"msg_f32aeb1ca001PjFXFv6kpjRCFZ"}}

